"""Stops a run early when a value in settings.py is outside the range written next to it."""
import settings


def need(condition, message):
    if not condition:
        raise ValueError("settings.py: " + message)


def check_settings():
    need(settings.PRESET in (None, "pv_x", "pv_x_r2"), "PRESET must be None, 'pv_x' or 'pv_x_r2'")
    need(settings.MODE in ("answer", "full"), "MODE must be 'answer' or 'full', got %r" % (settings.MODE,))
    need(0.25 <= settings.MAP_GSD <= 0.4, "MAP_GSD must be 0.25 to 0.4")
    need(len(settings.LEVELS) > 0 and all(isinstance(level, int) and 0 <= level <= 12 for level in settings.LEVELS), "LEVELS must be whole numbers 0 to 12")
    need(settings.TILE % 56 == 0, "TILE must be a multiple of 56")
    need(settings.QUERY_SET in ("standard", "all", "custom"), "QUERY_SET must be 'standard', 'all' or 'custom'")
    need(0.0 in settings.HEADINGS, "HEADINGS must contain 0.0")
    need(all(-15 <= heading <= 15 for heading in settings.HEADINGS), "HEADINGS must be between -15 and 15 degrees")
    need(1.0 in settings.SCALE_FACTORS, "SCALE_FACTORS must contain 1.0")
    need(all(0.5 <= factor <= 1.5 for factor in settings.SCALE_FACTORS), "SCALE_FACTORS must be between 0.5 and 1.5")
    need(5000 <= settings.DISC_RADIUS <= 7000, "DISC_RADIUS must be 5000 to 7000 metres")
    need(1 <= settings.M_FINE <= settings.K_PEAKS <= 200, "need 1 <= M_FINE <= K_PEAKS <= 200")
    need(settings.TIME_BUDGET_S is None or 5 <= settings.TIME_BUDGET_S <= 29, "TIME_BUDGET_S must be None or 5 to 29 seconds")
    need(settings.FFT_BACKEND in ("auto", "torch", "matmul"), "FFT_BACKEND must be 'auto', 'torch' or 'matmul'")
    need(0 <= settings.DINO_WEIGHT <= 100, "DINO_WEIGHT must be 0 to 100")
    need(settings.DINO_ONLY_BELOW_M is None or 0 <= settings.DINO_ONLY_BELOW_M <= 5000, "DINO_ONLY_BELOW_M must be None or 0 to 5000")
    need(0.2 <= settings.LOFTR_CONFIDENCE < 1, "LOFTR_CONFIDENCE must be 0.2 to below 1")
    need(0 < settings.LOFTR_COARSE_THRESHOLD < 1, "LOFTR_COARSE_THRESHOLD must be between 0 and 1")
    need(0 < settings.RANSAC_PIXELS <= 8, "RANSAC_PIXELS must be above 0 and at most 8")
    need(1 <= settings.MAX_SHIFT_CELLS <= 6, "MAX_SHIFT_CELLS must be 1 to 6")
    need(settings.LOFTR_REUSE_QUERY in (True, False), "LOFTR_REUSE_QUERY must be True or False")
    need(1 <= settings.LOFTR_BATCH <= 25, "LOFTR_BATCH must be 1 to 25")
    need(settings.SECOND_PASS_HEADINGS is None or all(-15 <= heading <= 15 for heading in settings.SECOND_PASS_HEADINGS), "SECOND_PASS_HEADINGS must be None or headings between -15 and 15")
    need(settings.SECOND_PASS_SCALES is None or all(0.5 <= factor <= 1.5 for factor in settings.SECOND_PASS_SCALES), "SECOND_PASS_SCALES must be None or scales between 0.5 and 1.5")
    need(settings.SECOND_PASS_MIN_INLIERS is None or settings.MIN_INLIERS <= settings.SECOND_PASS_MIN_INLIERS <= 30, "SECOND_PASS_MIN_INLIERS must be None or MIN_INLIERS to 30")
    need(settings.GAMMA >= 0, "GAMMA must be 0 or more")
    need(settings.MIN_INLIERS >= 1, "MIN_INLIERS must be 1 or more")
    need(settings.REFINE_FINER_LEVELS in (0, 1, 2), "REFINE_FINER_LEVELS must be 0, 1 or 2")
    need(settings.FALLBACK_MATCHER in (True, False), "FALLBACK_MATCHER must be True or False")
    need(settings.FALLBACK_NATIVE_FROM_HEIGHT_M is None or 0 <= settings.FALLBACK_NATIVE_FROM_HEIGHT_M <= 5000, "FALLBACK_NATIVE_FROM_HEIGHT_M must be None or 0 to 5000")
    need(settings.REFINE_NATIVE in (True, False) and settings.TILE_CENTRE_FIX in (True, False), "REFINE_NATIVE and TILE_CENTRE_FIX must be True or False")
    need(not settings.REFINE_NATIVE or settings.REFINE_FINER_LEVELS == 2, "REFINE_NATIVE needs REFINE_FINER_LEVELS = 2")
    need(4 <= settings.REFINE_MIN_INLIERS <= 30, "REFINE_MIN_INLIERS must be 4 to 30")
    need(0.5 <= settings.REFINE_MAX_SHIFT_SIGMA <= 4, "REFINE_MAX_SHIFT_SIGMA must be 0.5 to 4")
    need(settings.FLAT_FIELD_FROM_HEIGHT_M is None or 0 <= settings.FLAT_FIELD_FROM_HEIGHT_M <= 5000, "FLAT_FIELD_FROM_HEIGHT_M must be None or 0 to 5000")
    need(isinstance(settings.FLAT_FIELD_DEGREE, int) and 0 <= settings.FLAT_FIELD_DEGREE <= 6, "FLAT_FIELD_DEGREE must be a whole number 0 to 6")
    need(settings.LOCAL_NORM_SIGMA is None or 2 <= settings.LOCAL_NORM_SIGMA <= 60, "LOCAL_NORM_SIGMA must be None or 2 to 60")
    need(settings.PHOTO_MASK_RECTS is None or all(len(rect) == 4 and 0 <= rect[0] < rect[2] <= 320 and 0 <= rect[1] < rect[3] <= 256 for rect in settings.PHOTO_MASK_RECTS), "PHOTO_MASK_RECTS must be None or a list of (x0, y0, x1, y1) inside the 320 x 256 frame")
    need(settings.NATIVE_FINE_FROM_HEIGHT_M is None or 0 <= settings.NATIVE_FINE_FROM_HEIGHT_M <= 5000, "NATIVE_FINE_FROM_HEIGHT_M must be None or 0 to 5000")
    need(settings.NATIVE_FINE_LEVELS == 2, "NATIVE_FINE_LEVELS must be 2 (the only tested value)")
    need(settings.XOFTR_FROM_HEIGHT_M is None or 0 <= settings.XOFTR_FROM_HEIGHT_M <= 5000, "XOFTR_FROM_HEIGHT_M must be None or 0 to 5000")
    need(0.1 <= settings.XOFTR_COARSE_THRESHOLD <= 0.5 and 0.05 <= settings.XOFTR_FINE_THRESHOLD <= 0.5 and 0 <= settings.XOFTR_MIN_CONFIDENCE <= 0.5, "the XOFTR thresholds are out of range")
    need(settings.PHOTO_VIEW_FROM_HEIGHT_M is None or 0 <= settings.PHOTO_VIEW_FROM_HEIGHT_M <= 5000, "PHOTO_VIEW_FROM_HEIGHT_M must be None or 0 to 5000")
    need(8 <= settings.PHOTO_VIEW_MIN_INLIERS <= 60 and 5 <= settings.PHOTO_VIEW_LOCAL_NORM_PX <= 30 and 0.2 <= settings.PHOTO_VIEW_MIN_MAP_SHARE <= 1, "the PHOTO_VIEW settings are out of range")
    need(settings.PHOTO_VIEW_FIT_POSE in (True, False) and (not settings.PHOTO_VIEW_FIT_POSE or settings.PHOTO_VIEW_FROM_HEIGHT_M is not None), "PHOTO_VIEW_FIT_POSE must be True or False and needs PHOTO_VIEW_FROM_HEIGHT_M")
    need(0.3 <= settings.PHOTO_VIEW_PRIOR_TILT_DEG <= 4 and 0.5 <= settings.PHOTO_VIEW_PRIOR_YAW_DEG <= 8 and 0.005 <= settings.PHOTO_VIEW_PRIOR_HEIGHT <= 0.1 and 0.5 <= settings.PHOTO_VIEW_FIT_MAX_MOVE_SIGMA <= 8, "the PHOTO_VIEW prior settings are out of range")
    need(settings.PHOTO_VIEW_FIT_ROUNDS in (1, 2, 3), "PHOTO_VIEW_FIT_ROUNDS must be 1, 2 or 3")
    need(settings.PHOTO_VIEW_VERIFY_BELOW is None or 1 <= settings.PHOTO_VIEW_VERIFY_BELOW <= 200, "PHOTO_VIEW_VERIFY_BELOW must be None or 1 to 200")
    need(settings.PHOTO_VIEW_VERIFY_MAX_HEIGHT_M is None or 0 <= settings.PHOTO_VIEW_VERIFY_MAX_HEIGHT_M <= 5000, "PHOTO_VIEW_VERIFY_MAX_HEIGHT_M must be None or 0 to 5000")
    need(settings.PHOTO_VIEW_VERIFY_ACT in (True, False) and 1 <= settings.PHOTO_VIEW_VERIFY_MIN <= 60, "the PHOTO_VIEW_VERIFY settings are out of range")
    need(5 <= settings.NATIVE_FINE_LOCAL_NORM_PX <= 30, "NATIVE_FINE_LOCAL_NORM_PX must be 5 to 30")
    need(settings.BAR_BY_LEVEL is None or (isinstance(settings.BAR_BY_LEVEL, dict) and all(isinstance(k, int) and isinstance(v, int) and 1 <= v <= 30 for k, v in settings.BAR_BY_LEVEL.items())), "BAR_BY_LEVEL must be None or a dict of level -> bar (1 to 30)")
    need(not settings.USE_AGREEMENT or settings.QUERY_SET == "standard", "USE_AGREEMENT needs QUERY_SET 'standard' (queries 2.5 degrees apart do not agree independently)")
    need(2 <= settings.AGREE_MIN_QUERIES <= 4, "AGREE_MIN_QUERIES must be 2 to 4")
    need(0.5 <= settings.AGREE_RADIUS_SIGMA <= 2, "AGREE_RADIUS_SIGMA must be 0.5 to 2")
    need(2 <= settings.AGREE_QUERY_INLIERS <= 6, "AGREE_QUERY_INLIERS must be 2 to 6")
    need(settings.GUARD_PRIOR > 0 and settings.GUARD_PRIOR_WEIGHT > 0, "GUARD_PRIOR and GUARD_PRIOR_WEIGHT must be above 0")
    need(1.0 <= settings.GUARD_DEAD_ZONE <= 3, "GUARD_DEAD_ZONE must be 1 to 3")
    need(settings.USE_ALTERED_COPIES in (True, False), "USE_ALTERED_COPIES must be True or False")
    need(len(settings.ALTERED_COPY_KINDS) > 0 and all(kind in ("invert", "sharpen") for kind in settings.ALTERED_COPY_KINDS), "ALTERED_COPY_KINDS must list 'invert' and/or 'sharpen'")
    need(settings.ALTERED_COPY_BAR_ONLY in (True, False), "ALTERED_COPY_BAR_ONLY must be True or False")
    need(settings.ALTERED_COPIES_ORDER in ("before_second_pass", "after_second_pass"), "ALTERED_COPIES_ORDER must be 'before_second_pass' or 'after_second_pass'")
    need(not settings.USE_ALTERED_COPIES or settings.QUERY_SET == "standard", "USE_ALTERED_COPIES needs QUERY_SET 'standard' (a copy is decided like the first pass)")
    need(settings.USE_ALIGNED_RESCUE in (True, False), "USE_ALIGNED_RESCUE must be True or False")
    need(0.05 <= settings.ALIGNED_CONFIDENCE <= 0.2, "ALIGNED_CONFIDENCE must be 0.05 to 0.2")
    need(1 <= settings.ALIGNED_TOLERANCE_M <= 30, "ALIGNED_TOLERANCE_M must be 1 to 30")
    need(0 <= settings.ALIGNED_MIN_Z <= 100, "ALIGNED_MIN_Z must be 0 to 100")
    need(0 <= settings.ALIGNED_MARGIN <= 50, "ALIGNED_MARGIN must be 0 to 50")
    need(1 <= settings.ALIGNED_FAR_SIGMA <= 4, "ALIGNED_FAR_SIGMA must be 1 to 4")
    need(not settings.USE_ALIGNED_RESCUE or settings.LOFTR_COARSE_THRESHOLD <= settings.ALIGNED_CONFIDENCE, "USE_ALIGNED_RESCUE needs LOFTR_COARSE_THRESHOLD <= ALIGNED_CONFIDENCE (weak matches must exist)")
    for key in ("attitude", "pitch_sign", "roll_sign", "yaw_offset", "scale", "height_offset"):
        need(key in settings.GEOMETRY, "GEOMETRY has no key %r" % key)
